import ida_bytes
# Read strings at various callback-related addresses
addrs = [0x142555364, 0x142597f99, 0x1424c6295, 0x1424BD2C0]
results = []
for addr in addrs:
    raw = ida_bytes.get_bytes(addr, 40)
    if raw:
        for i in range(len(raw)):
            if raw[i] == 0:
                s = raw[:i].decode(errors='replace')
                results.append({'addr': hex(addr), 'str': s})
                break
        else:
            s = raw.decode(errors='replace')
            results.append({'addr': hex(addr), 'str': s})
results
